-- ===== schema.sql =====
-- ==============================================================================
-- VISART DATABASE SCHEMA (Supabase PostgreSQL)
-- Multi-member Unified Platform Layer
-- ==============================================================================

-- Enable UUID extension
create extension if not exists "pgcrypto";
create extension if not exists "uuid-ossp";

-- 1. ARTISANS TABLE
create table if not exists public.artisans (
  id uuid primary key default gen_random_uuid(),
  name text not null,
  location text,
  craft text,
  preferred_language text default 'en',
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now()
);

-- 2. PRODUCTS TABLE
create table if not exists public.products (
  id text primary key default gen_random_uuid()::text,
  artisan_id uuid references public.artisans(id) on delete set null,
  image_url text,
  input_data jsonb not null default '{}'::jsonb,
  generated_data jsonb default '{}'::jsonb,
  is_published boolean default true,
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now()
);

-- Indexes for performance
create index if not exists idx_products_artisan_id on public.products(artisan_id);
create index if not exists idx_products_created_at on public.products(created_at desc);

-- 3. ROW LEVEL SECURITY (RLS) POLICIES NOTE: every policy below is unconditionally permissive
-- (`using (true)` / `with check (true)`). RLS is enabled but enforces no restriction — any holder
-- of the public anon key can read/write every row in every table here. There is no
-- user_id/ownership column to scope these policies to. Enable RLS
alter table public.artisans enable row level security;
alter table public.products enable row level security;

-- Public policies
drop policy if exists "Allow public read on artisans" on public.artisans;
create policy "Allow public read on artisans"
  on public.artisans for select
  using (true);

drop policy if exists "Allow public insert on artisans" on public.artisans;
create policy "Allow public insert on artisans"
  on public.artisans for insert
  with check (true);

drop policy if exists "Allow public update on artisans" on public.artisans;
create policy "Allow public update on artisans"
  on public.artisans for update
  using (true);

drop policy if exists "Allow public read on products" on public.products;
create policy "Allow public read on products"
  on public.products for select
  using (true);

drop policy if exists "Allow public insert on products" on public.products;
create policy "Allow public insert on products"
  on public.products for insert
  with check (true);

drop policy if exists "Allow public update on products" on public.products;
create policy "Allow public update on products"
  on public.products for update
  using (true);

-- 4. STORAGE BUCKET SETUP
insert into storage.buckets (id, name, public)
values ('product-images', 'product-images', true)
on conflict (id) do nothing;

drop policy if exists "Public Access to product-images" on storage.objects;
create policy "Public Access to product-images"
  on storage.objects for select
  using (bucket_id = 'product-images');

drop policy if exists "Public Upload to product-images" on storage.objects;
create policy "Public Upload to product-images"
  on storage.objects for insert
  with check (bucket_id = 'product-images');

drop policy if exists "Public Update to product-images" on storage.objects;
create policy "Public Update to product-images"
  on storage.objects for update
  using (bucket_id = 'product-images');

-- 5. PRODUCT FEEDBACK & AUTHENTICITY REVIEWS TABLE
create table if not exists public.product_feedback (
  id text primary key,
  product_id text not null references public.products(id) on delete cascade,
  user_name text not null,
  user_location text,
  is_verified_buyer boolean default true,
  rating integer not null check (rating >= 1 and rating <= 5),
  authenticity_rating text not null check (authenticity_rating in ('GENUINE_HANDCRAFTED', 'LIKELY_GENUINE', 'SUSPICIOUS_QUALITY', 'CONFIRMED_FAKE_REPLICA')),
  comment text not null,
  craft_checks jsonb default '{}'::jsonb,
  suspected_counterfeit_reason text,
  flagged_as_fake boolean default false,
  helpful_count integer default 0,
  gemini_analysis jsonb default '{}'::jsonb,
  created_at timestamptz not null default now()
);

create index if not exists idx_feedback_product_id on public.product_feedback(product_id);
create index if not exists idx_feedback_created_at on public.product_feedback(created_at desc);

alter table public.product_feedback enable row level security;

drop policy if exists "Allow public read on product_feedback" on public.product_feedback;
create policy "Allow public read on product_feedback"
  on public.product_feedback for select
  using (true);

drop policy if exists "Allow public insert on product_feedback" on public.product_feedback;
create policy "Allow public insert on product_feedback"
  on public.product_feedback for insert
  with check (true);

-- ===== migrations/0001_create_admin_users.sql =====
--
-- Purpose: introduce a dedicated `admin_users` table to back custom admin
-- authentication (replacing the hardcoded, client-side-only credentials in
-- components/admin/AdminLoginPage.tsx — that replacement happens in a later,
-- separately reviewed batch; this migration only adds the table).
--
-- This repository has no migration tool and no `supabase/migrations/` convention prior to this
-- file. This migration follows the same manual-application model; see supabase/migrations/README.md
-- for the exact application procedure.
--
-- Security posture (do not weaken without a documented reason):
--   - RLS is enabled with ZERO policies defined below. This means every role
--     subject to RLS (anon, authenticated) is denied all access by default.
--     Only a service-role connection (which bypasses RLS) or a direct
--     Supabase SQL editor / postgres-role session can read or write this table.
--   - No SELECT/INSERT/UPDATE/DELETE policy is defined for anon or authenticated
--     roles. Do not add one for this table without an explicit, reviewed reason —
--     admin_users.password_hash must never be reachable via the public anon key.
--   - This migration does not touch any policy on products, artisans,
--     product_feedback, or storage.objects. Existing public workflows are
--     unaffected.
--
-- ==============================================================================

create table if not exists public.admin_users (
  id uuid primary key default gen_random_uuid(),
  email text not null,
  password_hash text not null,
  is_active boolean not null default true,
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now()
);

-- Case-insensitive, whitespace-insensitive uniqueness. This must stay in agreement
-- with lib/auth/email.ts's normalizeEmail() (trim + lowercase) — both sides apply
-- the exact same two transformations (trim, then lowercase), so an email that the
-- application treats as a duplicate is also rejected at the database level even if
-- application-level normalization is ever bypassed or has a bug.
create unique index if not exists admin_users_normalized_email_idx
  on public.admin_users (lower(trim(email)));

-- Enable RLS with no policies: default-deny for anon and authenticated roles.
alter table public.admin_users enable row level security;

-- Defense in depth: explicitly strip any default schema-level grants, so a
-- misconfigured project default (e.g. default privileges granting SELECT to
-- anon/authenticated on new tables) cannot expose this table even before RLS
-- is considered. This does not change grants on any other existing table.
revoke all on public.admin_users from anon, authenticated;

-- ===== migrations/0002_create_admin_sessions.sql =====
--
-- Purpose: back custom admin session issuance/validation/logout (app/api/admin/auth/*,
-- lib/auth/session.ts) with a real, revocable, database-backed session store. Only a
-- SHA-256 hash of each session token is ever stored here — the raw token is never
-- persisted anywhere, only held in the browser's HttpOnly cookie (see lib/auth/cookie.ts).
--
-- Follows the migration convention established in 0001_create_admin_users.sql /
-- supabase/migrations/README.md: a single hand-written, manually-applied SQL file.
-- Not applied to any database as part of this change.
--
-- Security posture (do not weaken without a documented reason):
--   - RLS is enabled with ZERO policies, same as admin_users. Default-deny for anon and
--     authenticated. Only a service-role connection (lib/auth/supabaseServiceClient.ts) or a
--     direct SQL-editor/postgres-role session can read or write this table.
--   - admin_user_id cascades on delete from admin_users, so deleting an admin account also
--     removes its sessions (defense in depth alongside the application-level session
--     revocation in lib/auth/session.ts when is_active is false).
--   - This migration does not touch admin_users' columns, or any policy on products,
--     artisans, product_feedback, or storage.objects.
--
-- ==============================================================================

create table if not exists public.admin_sessions (
  id uuid primary key default gen_random_uuid(),
  admin_user_id uuid not null references public.admin_users(id) on delete cascade,
  token_hash text not null,
  expires_at timestamptz not null,
  created_at timestamptz not null default now(),
  last_used_at timestamptz
);

-- Every validation does an exact lookup by token_hash (lib/auth/session.ts:
-- validateSessionToken) — this unique index both enforces "one row per hash" and is the
-- index that lookup query actually uses.
create unique index if not exists admin_sessions_token_hash_idx
  on public.admin_sessions (token_hash);

-- Supports: (a) revoking/listing all sessions for a given admin when is_active flips to
-- false (lib/auth/session.ts), and (b) a future housekeeping job deleting rows past
-- expires_at without a full table scan.
create index if not exists admin_sessions_admin_user_id_idx
  on public.admin_sessions (admin_user_id);

create index if not exists admin_sessions_expires_at_idx
  on public.admin_sessions (expires_at);

-- Enable RLS with no policies: default-deny for anon and authenticated roles.
alter table public.admin_sessions enable row level security;

-- Defense in depth, same as admin_users.
revoke all on public.admin_sessions from anon, authenticated;

-- ===== migrations/0003_create_ml_tables.sql =====
-- ML verification results. Written and read only by the server with the service-role key:
-- row level security is on with no policies, and the public roles have no grants.
-- Requires supabase/schema.sql and 0001_create_admin_users.sql. Apply manually; see README.md.

create extension if not exists vector;

create table if not exists public.listing_checks (
  product_id text primary key references public.products(id) on delete cascade,
  status text not null default 'pending' check (status in ('pending', 'checked', 'failed')),
  model_version text,
  predicted_class text check (predicted_class in ('pottery', 'wood', 'textile', 'metal', 'bamboo', 'uncertain')),
  confidence real check (confidence between 0 and 1),
  claim_result text check (claim_result in ('match', 'mismatch', 'cannot_tell')),
  quality jsonb,
  duplicate_of text references public.products(id) on delete set null,
  similarity real,
  review_label text,
  reviewed_by uuid references public.admin_users(id) on delete set null,
  reviewed_at timestamptz,
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now()
);

create table if not exists public.image_embeddings (
  product_id text primary key references public.products(id) on delete cascade,
  embedding vector(512) not null,
  model_version text not null,
  created_at timestamptz not null default now()
);

alter table public.listing_checks enable row level security;
alter table public.image_embeddings enable row level security;
revoke all on public.listing_checks from anon, authenticated;
revoke all on public.image_embeddings from anon, authenticated;

-- Closest stored image by cosine similarity. Exact scan: enough at project scale.
create or replace function public.match_image_embeddings(
  query vector(512),
  exclude_product text,
  min_similarity float
)
returns table (product_id text, similarity float)
language sql stable
as $$
  select e.product_id, 1 - (e.embedding <=> query) as similarity
  from public.image_embeddings e
  where e.product_id <> exclude_product
    and 1 - (e.embedding <=> query) >= min_similarity
  order by e.embedding <=> query
  limit 1;
$$;

revoke all on function public.match_image_embeddings(vector, text, float) from public, anon, authenticated;
grant execute on function public.match_image_embeddings(vector, text, float) to service_role;

commit;

